  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255); // Blue sky
  brush.beginShape();
  brush.vertex(0, 0, 0);       // Top left
  brush.vertex(400, 0, 0);     // Top right
  brush.vertex(200, 400, 0);   // Bottom center
  brush.endShape(true);

  // Hills
  brush.fill("#90EE90", 255);  // Light green hills
  brush.beginShape();
  brush.vertex(0, 300, 0);     // Hill top left
  brush.vertex(400, 300, 0);   // Hill top right
  brush.vertex(200, 400, 0);   // Hill bottom center
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 255);  // Yellow sun
  brush.beginShape();
  brush.vertex(150, 150, 0);   // Sun top
  brush.vertex(250, 100, 0);   // Sun bottom right
  brush.vertex(350, 150, 0);   // Sun bottom left
  brush.endShape(true);
}
