  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255); // Blue sky
  brush.beginShape();
  brush.vertex(0, 0, 0);     // Top left
  brush.vertex(400, 0, 0);  // Top right
  brush.vertex(200, 400, 0); // Bottom center
  brush.endShape(true);

  // Green hills
  brush.fill("#98FB98", 255); // Green hills
  brush.beginShape();
  brush.vertex(0, 200, 0);   // Hill top left
  brush.vertex(400, 200, 0); // Hill top right
  brush.vertex(200, 300, 0); // Hill middle
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 255); // Orange sun
  brush.beginShape();
  brush.vertex(200, 100, 0); // Sun top
  brush.vertex(250, 150, 0); // Sun middle
  brush.vertex(150, 150, 0); // Sun middle
  brush.endShape(true);
}

