  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255); // Sky blue
  brush.beginShape();
  brush.vertex(0, 0);       // Top left
  brush.vertex(400, 0);     // Top right
  brush.vertex(200, 400);   // Bottom center
  brush.endShape(true);

  // Green hills
  brush.fill("#98FB98", 255); // Green
  brush.beginShape();
  brush.vertex(0, 200);     // Hill top left
  brush.vertex(400, 200);   // Hill top right
  brush.vertex(200, 300);   // Hill bottom center
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 255); // Yellow
  brush.beginShape();
  brush.vertex(200, 100);   // Sun top
  brush.vertex(300, 100);   // Sun top right
  brush.vertex(250, 200);   // Sun bottom
  brush.endShape(true);
}
```

