  // Sun
  brush.fill("#FFD700", 255); // Yellow sun
  brush.beginShape();
  brush.vertex(100, 250);     // Sun top
  brush.vertex(300, 250);     // Sun top right
  brush.vertex(200, 150);     // Sun bottom
  brush.endShape(true);
}
